; =====================================================================
;  TITLE.ASM -- the title screen (T-REL-1, D46)
;
;  Shown once at start-up: the ACADIA logo (TITLE_GFX.ASM, generated by
;  tools/mktitle.py) in the map's colours, sea blue behind grass green
;  letters with beach-yellow edges and a black shadow, then
;  "REBUILD YOUR WORLD" and a prompt.  The title tune plays.  Fire,
;  START or any key, once everything has been let go, goes on to the
;  setup screen, with the tune still playing.  Left alone for DM_IDLE
;  seconds, it plays the demo (DEMO.ASM), which comes back here.
;
;  Its display list, TDLIST, sits in DLIST's page like SUDLIST.  The
;  two text lines are built in the map's screen memory (MAPSCR), which
;  the setup screen clears and the game redraws.
; =====================================================================

GS_TITLE = 5            ; GSTATE while the title screen is up
TITLEGFX = $8000        ; the logo bitmap (TITLE_GFX.ASM; 48K or more)

TT_SCR  =  MAPSCR       ; mode 7 line (20 bytes), then mode 6 (20)
TT_WHT  =  $C0          ; mode 6/7 colour bits: COLPF3, white
TT_YEL  =  $40          ; COLPF1, yellow

; ---------------------------------------------------------------------
;  TITLE_ENTER -- show the title screen.  Trashes A, X, Y.
; ---------------------------------------------------------------------
TITLE_ENTER
        JSR MUS_TITLE
        LDA #GS_TITLE
        STA GSTATE
        LDA #0
        STA TI_ARM
        STA TI_SEC
        JSR PM_HIDE     ; no cursors, fish, weather or pirates
        JSR TIC_SYNC    ; idle time counts from now
        LDX #19         ; the two text lines, with their colours
TE_TXT  LDA TT_SUB,X
        ORA #TT_WHT
        STA TT_SCR,X
        LDA TT_PRM,X
        ORA #TT_YEL
        STA TT_SCR+20,X
        DEX
        BPL TE_TXT
        JSR TI_COLS     ; the ROM font
        LDA #C_SEA      ; the map's palette (D16)
        STA COLOR4
        LDA #C_GRASS
        STA COLOR0
        LDA #C_LIGHT
        STA COLOR1
        LDA #C_DARK
        STA COLOR2
        LDA #C_WHITE
        STA COLOR3
        LDA #<TDLIST    ; same page as DLIST: one store switches
        STA SDLSTL
        RTS

; ---------------------------------------------------------------------
;  TITLE_FRAME -- each frame of the title screen: once everything is
;  let go, fire, START or any key goes on to the setup screen; after
;  DM_IDLE seconds with nothing touched, the demo.  Trashes A, X, Y.
; ---------------------------------------------------------------------
TITLE_FRAME
        LDA JOY0        ; anything touched: idle time from 0
        ORA JOY1
        ORA FIRE0
        ORA FIRE1
        ORA KEYDOWN
        ORA CONKEY
        BEQ TF_IDLE
        LDA #0
        STA TI_SEC
TF_IDLE JSR TIC_POLL    ; count the idle seconds
TF_TIC  JSR TIC_NEXT
        BCC TF_TDON
        BNE TF_TIC      ; not a new second
        INC TI_SEC
        BNE TF_TIC
TF_TDON LDA TI_SEC
        CMP #DM_IDLE
        BCC TF_KEYS
        JMP DEMO_GO
TF_KEYS LDA FIRE0
        ORA FIRE1
        ORA KEYDOWN
        ORA CONKEY
        LDX TI_ARM
        BNE TF_ARMED
        CMP #0
        BNE TF_DONE     ; still held (OPTION at power-on, say)
        INC TI_ARM
TF_DONE RTS
TF_ARMED
        CMP #0
        BEQ TF_DONE
        JMP SETUP_ENTER

; TI_COLS -- the ROM font and the text colours for the title and setup
; screens.  Trashes A.
TI_COLS LDA #ROMFONT
        STA CHBAS
        LDA #C_STXT
        STA COLOR1
        LDA #C_SBAR
        STA COLOR2
        LDA #C_SBRD
        STA COLOR4
        RTS

; the text lines, 20 characters each (screen codes; colour added above)
TT_SUB  .SBYTE " REBUILD YOUR WORLD "
TT_PRM  .SBYTE " PRESS FIRE TO PLAY "
